:root {
  /* Brand Colors */
  --indigo-900: #1e1b4b;
  --indigo-800: #3730a3;
  --indigo-700: #4338ca;
  --indigo-600: #6366f1;
  --indigo-500: #818cf8;
  --indigo-100: #e0e7ff;

  --purple-700: #7c3aed;
  --purple-600: #8b5cf6;
  --purple-500: #a78bfa;

  --teal-600: #0d9488;
  --teal-500: #14b8a6;
  --teal-400: #2dd4bf;

  --cyan-500: #06b6d4;

  --slate-900: #0f172a;
  --slate-800: #1e293b;
  --slate-700: #334155;
  --slate-600: #475569;
  --slate-400: #94a3b8;
  --slate-300: #cbd5e1;
  --slate-200: #e2e8f0;
  --slate-100: #f1f5f9;
  --slate-50: #f8fafc;

  --amber-500: #f59e0b;
  --rose-500: #ef4444;
  --green-500: #22c55e;

  --gradient-primary: linear-gradient(135deg, #1e1b4b 0%, #3730a3 50%, #6366f1 100%);
  --gradient-accent: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%);
  --gradient-teal: linear-gradient(135deg, #0d9488 0%, #06b6d4 100%);
  --gradient-warm: linear-gradient(135deg, #f59e0b 0%, #ef4444 100%);
  --gradient-card: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.12), 0 1px 2px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 48px rgba(0,0,0,0.12);
  --shadow-glow: 0 0 40px rgba(99,102,241,0.15);

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

/* Reset */
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }
html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }
body { font-family: var(--font-sans); color: var(--slate-100); background: var(--slate-900); line-height: 1.6; overflow-x: hidden; }
img { max-width: 100%; height: auto; }
a { color: inherit; text-decoration: none; }

/* ===== UTILITY ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 100px 0; }
.section-label { font-family: var(--font-mono); font-size: 0.75rem; color: var(--indigo-500); text-transform: uppercase; letter-spacing: 0.12em; margin-bottom: 12px; font-weight: 700; }
.section-title { font-size: 2.8rem; font-weight: 800; line-height: 1.15; letter-spacing: -0.03em; margin-bottom: 16px; }
