.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }
.gradient-text { background: var(--gradient-accent); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.gradient-text-teal { background: var(--gradient-teal); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.gradient-text-warm { background: var(--gradient-warm); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }

/* ===== BUTTONS ===== */
.btn { display: inline-flex; align-items: center; gap: 8px; padding: 14px 32px; border-radius: var(--radius-sm); font-weight: 600; font-size: 0.95rem; transition: all 0.25s; cursor: pointer; border: none; font-family: inherit; white-space: nowrap; }
.btn:hover { transform: translateY(-2px); }
.btn-primary { background: var(--gradient-accent); color: #fff; box-shadow: 0 4px 20px rgba(99,102,241,0.3); }
.btn-primary:hover { box-shadow: 0 6px 28px rgba(99,102,241,0.45); }
.btn-teal { background: var(--gradient-teal); color: #fff; box-shadow: 0 4px 20px rgba(6,182,212,0.3); }
.btn-teal:hover { box-shadow: 0 6px 28px rgba(6,182,212,0.45); }
.btn-warm { background: var(--gradient-warm); color: #fff; box-shadow: 0 4px 20px rgba(245,158,11,0.3); }
.btn-warm:hover { box-shadow: 0 6px 28px rgba(245,158,11,0.45); }
.btn-outline { border: 2px solid var(--slate-600); color: var(--slate-200); background: transparent; }
.btn-outline:hover { border-color: var(--indigo-500); color: #fff; }
.btn-ghost { color: var(--indigo-400); background: transparent; }
.btn-ghost:hover { color: #fff; }
.btn-sm { padding: 10px 20px; font-size: 0.85rem; }
.btn-price { width: 100%; justify-content: center; padding: 12px; border-radius: var(--radius-sm); }

/* ===== NAVIGATION ===== */
nav { position: fixed; top: 0; left: 0; right: 0; z-index: 1000; background: rgba(15,23,42,0.85); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); border-bottom: 1px solid rgba(51,65,85,0.3); transition: all 0.3s; }
nav.scrolled { background: rgba(15,23,42,0.96); }
.nav-inner { display: flex; align-items: center; justify-content: space-between; padding: 16px 24px; max-width: 1200px; margin: 0 auto; }
.nav-logo { font-size: 1.4rem; font-weight: 800; letter-spacing: -0.02em; }
.nav-logo .accent { color: var(--indigo-500); }
.nav-links { display: flex; align-items: center; gap: 32px; list-style: none; }
.nav-links a { font-size: 0.88rem; font-weight: 500; color: var(--slate-300); transition: color 0.2s; position: relative; }
.nav-links a:hover { color: #fff; }
.nav-links .dropdown { position: relative; }
.nav-links .dropdown-content { display: none; position: absolute; top: 100%; left: 0; background: var(--slate-800); border: 1px solid var(--slate-700); border-radius: var(--radius-sm); padding: 8px; min-width: 220px; box-shadow: var(--shadow-lg); margin-top: 8px; }
.nav-links .dropdown:hover .dropdown-content { display: block; }
.nav-links .dropdown-content a { display: block; padding: 10px 16px; border-radius: 6px; font-size: 0.85rem; }
.nav-links .dropdown-content a:hover { background: var(--slate-700); }
.nav-links .dropdown-content a small { display: block; color: var(--slate-400); font-size: 0.75rem; margin-top: 2px; font-weight: 400; }
.nav-cta { display: flex; align-items: center; gap: 12px; }
.mobile-toggle { display: none; background: none; border: none; color: #fff; font-size: 1.5rem; cursor: pointer; }
