  .nav-links.open { display: flex; flex-direction: column; position: absolute; top: 100%; left: 0; right: 0; background: var(--slate-800); padding: 24px; gap: 16px; border-bottom: 1px solid var(--slate-700); }
  .nav-links.open + .nav-cta { display: flex; position: absolute; top: 100%; right: 24px; margin-top: -60px; }
}

/* ===== HERO ===== */
.hero { padding: 140px 0 80px; background: var(--gradient-primary); position: relative; overflow: hidden; }
.hero::before { content: ''; position: absolute; top: -50%; left: -30%; width: 100%; height: 200%; background: radial-gradient(ellipse at 30% 50%, rgba(99,102,241,0.12) 0%, transparent 60%); pointer-events: none; }
.hero::after { content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 1px; background: linear-gradient(90deg, transparent, rgba(99,102,241,0.5), transparent); }
.hero-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; position: relative; z-index: 1; }
.hero-badge { display: inline-flex; align-items: center; gap: 8px; padding: 6px 16px; background: rgba(99,102,241,0.15); border: 1px solid rgba(99,102,241,0.3); border-radius: 20px; font-size: 0.82rem; color: var(--indigo-300); margin-bottom: 24px; font-family: var(--font-mono); }
.hero h1 { font-size: 3.6rem; font-weight: 900; line-height: 1.08; letter-spacing: -0.03em; margin-bottom: 20px; }
.hero h1 .highlight { background: var(--gradient-accent); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.hero p { font-size: 1.15rem; color: var(--slate-400); line-height: 1.7; max-width: 540px; margin-bottom: 32px; }
.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; margin-bottom: 48px; }
.hero-stats { display: flex; gap: 40px; padding-top: 32px; border-top: 1px solid rgba(51,65,85,0.4); }
.hero-stat .num { font-size: 1.6rem; font-weight: 800; }
.hero-stat .num.indigo { color: var(--indigo-400); }
.hero-stat .num.teal { color: var(--teal-400); }
.hero-stat .num.amber { color: var(--amber-500); }
.hero-stat .label { font-size: 0.82rem; color: var(--slate-500); }
.hero-visual { position: relative; display: flex; align-items: center; justify-content: center; }
.hero-graphic { width: 100%; max-width: 520px; }
.hero-graphic svg { width: 100%; height: auto; }
@media (max-width: 1024px) { 
  .hero-grid { grid-template-columns: 1fr; gap: 40px; }
  .hero h1 { font-size: 2.6rem; }
  .hero-stats { gap: 24px; flex-wrap: wrap; }
}

/* ===== TRUST BAR ===== */
.trust-bar { padding: 48px 0; border-bottom: 1px solid var(--slate-800); }
.trust-bar p { text-align: center; font-size: 0.85rem; color: var(--slate-500); text-transform: uppercase; letter-spacing: 0.1em; margin-bottom: 24px; }
.trust-logos { display: flex; justify-content: center; align-items: center; gap: 40px; flex-wrap: wrap; }
.trust-logo { height: 32px; opacity: 0.4; transition: opacity 0.2s; filter: grayscale(1); }
.trust-logo:hover { opacity: 0.8; filter: grayscale(0); }

/* ===== AWARDS ===== */
.awards { background: var(--slate-800); }
.awards-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 48px; }
.award-card { background: var(--slate-900); border: 1px solid var(--slate-700); border-radius: var(--radius-md); padding: 28px; text-align: center; transition: all 0.3s; }
.award-card:hover { border-color: var(--indigo-600); transform: translateY(-4px); box-shadow: var(--shadow-glow); }
.award-icon { font-size: 2.4rem; margin-bottom: 12px; }
.award-card h4 { font-size: 1rem; margin-bottom: 6px; }
.award-card p { font-size: 0.82rem; color: var(--slate-400); line-height: 1.5; }
@media (max-width: 768px) { .awards-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 480px) { .awards-grid { grid-template-columns: 1fr; } }

/* ===== AI CONSULTING (Reframed) ===== */
.consulting { background: var(--gradient-card); position: relative; }
.consulting::before { content: ''; position: absolute; top: 0; right: 0; width: 400px; height: 400px; background: radial-gradient(circle, rgba(99,102,241,0.06) 0%, transparent 70%); pointer-events: none; }
.consulting-header { margin-bottom: 48px; }
.consulting-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.consulting-card { background: rgba(30,41,59,0.6); border: 1px solid var(--slate-700); border-radius: var(--radius-md); padding: 32px; transition: all 0.3s; backdrop-filter: blur(4px); }
.consulting-card:hover { border-color: var(--indigo-600); transform: translateY(-4px); box-shadow: var(--shadow-glow); }
.consulting-card .icon { font-size: 2rem; margin-bottom: 16px; }
.consulting-card h3 { font-size: 1.15rem; margin-bottom: 8px; }
.consulting-card p { font-size: 0.88rem; color: var(--slate-400); line-height: 1.7; }
.consulting-card .tag { display: inline-block; margin-top: 12px; padding: 4px 10px; background: rgba(99,102,241,0.1); border: 1px solid rgba(99,102,241,0.2); border-radius: 12px; font-size: 0.72rem; color: var(--indigo-400); font-family: var(--font-mono); }
.consulting-compare { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 48px; }
.consulting-compare-card { border-radius: var(--radius-md); padding: 28px; }
.consulting-compare-card.old { background: rgba(239,68,68,0.05); border: 1px solid rgba(239,68,68,0.15); }
.consulting-compare-card.new { background: rgba(99,102,241,0.08); border: 1px solid rgba(99,102,241,0.2); }
.consulting-compare-card h4 { font-size: 1rem; margin-bottom: 12px; }
.consulting-compare-card ul { list-style: none; }
.consulting-compare-card li { padding: 6px 0; font-size: 0.88rem; color: var(--slate-400); }
.consulting-compare-card li::before { margin-right: 8px; }
.consulting-compare-card.old li::before { content: '✗'; color: var(--rose-500); }
.consulting-compare-card.new li::before { content: '✓'; color: var(--green-500); }
@media (max-width: 768px) { .consulting-grid, .consulting-compare { grid-template-columns: 1fr; } }
@media (max-width: 1024px) { .consulting-grid { grid-template-columns: repeat(2, 1fr); } }

/* ===== PRODUCT SUITE ===== */
.products { position: relative; }
.products::before { content: ''; position: absolute; top: 0; left: 0; width: 300px; height: 300px; background: radial-gradient(circle, rgba(6,182,212,0.06) 0%, transparent 70%); pointer-events: none; }
.products::after { content: ''; position: absolute; bottom: 0; right: 0; width: 400px; height: 400px; background: radial-gradient(circle, rgba(139,92,246,0.06) 0%, transparent 70%); pointer-events: none; }
.products-header { margin-bottom: 56px; }
.products-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; position: relative; z-index: 1; }
.product-card { background: var(--gradient-card); border: 1px solid var(--slate-700); border-radius: var(--radius-lg); overflow: hidden; transition: all 0.4s; }
.product-card:hover { transform: translateY(-8px); border-color: transparent; }
.product-card.hypatia:hover { box-shadow: 0 8px 40px rgba(99,102,241,0.2); }
.product-card.accelerator:hover { box-shadow: 0 8px 40px rgba(6,182,212,0.2); }
.product-card.vibra:hover { box-shadow: 0 8px 40px rgba(245,158,11,0.2); }
.product-card-top { height: 180px; display: flex; align-items: center; justify-content: center; font-size: 4rem; position: relative; }
.product-card-top.hypatia-bg { background: linear-gradient(135deg, rgba(99,102,241,0.2) 0%, rgba(139,92,246,0.15) 100%); }
.product-card-top.accelerator-bg { background: linear-gradient(135deg, rgba(6,182,212,0.2) 0%, rgba(59,130,246,0.15) 100%); }
.product-card-top.vibra-bg { background: linear-gradient(135deg, rgba(245,158,11,0.2) 0%, rgba(239,68,68,0.15) 100%); }
.product-card-body { padding: 28px; }
.product-card-body h3 { font-size: 1.3rem; font-weight: 700; margin-bottom: 8px; }
.product-card-body .tagline { font-size: 0.88rem; color: var(--slate-400); line-height: 1.6; margin-bottom: 16px; }
.product-features { list-style: none; margin-bottom: 24px; }
.product-features li { padding: 6px 0; font-size: 0.85rem; color: var(--slate-300); border-bottom: 1px solid rgba(51,65,85,0.3); }
.product-features li:last-child { border-bottom: none; }
.product-features li::before { margin-right: 8px; font-weight: 700; }
.product-features li.indigo::before { content: '✦'; color: var(--indigo-400); }
.product-features li.teal::before { content: '✦'; color: var(--teal-400); }
