.product-card-actions { display: flex; gap: 10px; flex-wrap: wrap; }
@media (max-width: 1024px) { .products-grid { grid-template-columns: 1fr; max-width: 500px; margin: 0 auto; } }

/* ===== ECOSYSTEM INFOGRAPHIC ===== */
.ecosystem { background: var(--slate-800); }
.ecosystem-visual { max-width: 900px; margin: 48px auto 0; background: var(--slate-900); border: 1px solid var(--slate-700); border-radius: var(--radius-lg); padding: 40px; }
.ecosystem-visual svg { width: 100%; height: auto; display: block; }

/* ===== METHODOLOGY ===== */
.methodology { position: relative; }
.methodology-tabs { display: flex; gap: 12px; margin-bottom: 40px; justify-content: center; flex-wrap: wrap; }
.methodology-tab { padding: 10px 24px; border-radius: 20px; border: 1px solid var(--slate-700); background: transparent; color: var(--slate-400); font-family: inherit; font-size: 0.88rem; cursor: pointer; transition: all 0.2s; }
.methodology-tab.active, .methodology-tab:hover { background: var(--indigo-600); border-color: var(--indigo-600); color: #fff; }
.methodology-content { display: none; max-width: 900px; margin: 0 auto; }
.methodology-content.active { display: block; }
.methodology-content svg { width: 100%; height: auto; background: var(--slate-800); border: 1px solid var(--slate-700); border-radius: var(--radius-lg); padding: 32px; }

/* ===== PRICING ===== */
.pricing { background: var(--gradient-card); }
.pricing-header { margin-bottom: 48px; }
.pricing-switch { display: flex; align-items: center; justify-content: center; gap: 12px; margin-bottom: 40px; font-size: 0.9rem; color: var(--slate-400); }
.pricing-switch .toggle { width: 48px; height: 26px; background: var(--slate-700); border-radius: 13px; cursor: pointer; position: relative; transition: background 0.3s; }
.pricing-switch .toggle.active { background: var(--indigo-600); }
.pricing-switch .toggle::after { content: ''; position: absolute; top: 3px; left: 3px; width: 20px; height: 20px; background: #fff; border-radius: 50%; transition: transform 0.3s; }
.pricing-switch .toggle.active::after { transform: translateX(22px); }
.pricing-tiers { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; max-width: 1000px; margin: 0 auto; }
.pricing-card { background: var(--slate-800); border: 1px solid var(--slate-700); border-radius: var(--radius-lg); padding: 32px; transition: all 0.3s; position: relative; }
.pricing-card:hover { transform: translateY(-4px); }
.pricing-card.featured { border-color: var(--indigo-600); box-shadow: 0 0 40px rgba(99,102,241,0.1); }
.pricing-card.featured .pricing-badge { position: absolute; top: -12px; left: 50%; transform: translateX(-50%); background: var(--gradient-accent); padding: 4px 20px; border-radius: 20px; font-size: 0.78rem; font-weight: 600; }
.pricing-card h3 { font-size: 1.15rem; margin-bottom: 4px; }
.pricing-card .sub { font-size: 0.82rem; color: var(--slate-500); margin-bottom: 16px; }
.pricing-card .price { font-size: 2.4rem; font-weight: 800; margin-bottom: 4px; }
.pricing-card .price small { font-size: 0.9rem; font-weight: 400; color: var(--slate-400); }
.pricing-card .price-desc { font-size: 0.82rem; color: var(--slate-500); margin-bottom: 24px; }
.pricing-card ul { list-style: none; margin-bottom: 24px; }
.pricing-card ul li { padding: 8px 0; font-size: 0.88rem; color: var(--slate-300); border-bottom: 1px solid rgba(51,65,85,0.3); }
.pricing-card ul li:last-child { border-bottom: none; }
.pricing-card ul li::before { content: '✓'; margin-right: 10px; color: var(--green-500); font-weight: 700; }
@media (max-width: 768px) { .pricing-tiers { grid-template-columns: 1fr; max-width: 400px; } }

/* ===== INDUSTRY EXPERTISE ===== */
.industry { background: var(--slate-800); }
.industry-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 40px; }
.industry-card { background: var(--slate-900); border: 1px solid var(--slate-700); border-radius: var(--radius-md); padding: 28px; text-align: center; transition: all 0.3s; }
.industry-card:hover { border-color: var(--indigo-600); transform: translateY(-4px); }
.industry-card .icon { font-size: 2.4rem; margin-bottom: 12px; }
.industry-card h4 { font-size: 1rem; margin-bottom: 8px; }
.industry-card p { font-size: 0.82rem; color: var(--slate-400); line-height: 1.5; }
@media (max-width: 768px) { .industry-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 480px) { .industry-grid { grid-template-columns: 1fr; } }

/* ===== CONTACT ===== */
.contact-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: start; }
.contact-info h3 { font-size: 1.5rem; margin-bottom: 16px; }
.contact-info p { color: var(--slate-400); line-height: 1.7; margin-bottom: 24px; }
.contact-detail { display: flex; gap: 12px; margin-bottom: 16px; align-items: flex-start; }
.contact-detail .icon { font-size: 1.2rem; margin-top: 2px; }
.contact-detail .detail-label { font-size: 0.82rem; color: var(--slate-500); }
.contact-form { background: var(--slate-800); border: 1px solid var(--slate-700); border-radius: var(--radius-md); padding: 32px; }
.contact-form h3 { font-size: 1.15rem; margin-bottom: 20px; }
.form-group { margin-bottom: 16px; }
.form-group label { display: block; font-size: 0.85rem; color: var(--slate-400); margin-bottom: 6px; }
.form-group input, .form-group textarea, .form-group select { width: 100%; padding: 12px 16px; background: var(--slate-900); border: 1px solid var(--slate-700); border-radius: var(--radius-sm); color: #fff; font-family: inherit; font-size: 0.9rem; transition: border 0.2s; }
.form-group input:focus, .form-group textarea:focus { outline: none; border-color: var(--indigo-500); }
.form-group textarea { resize: vertical; min-height: 100px; }
.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
@media (max-width: 768px) { .contact-grid { grid-template-columns: 1fr; } .form-row { grid-template-columns: 1fr; } }

